const skillsRows = $('Read Skills Tab').all().map(i => i.json);
const certsRows = $('Read Certifications Tab').all().map(i => i.json);
const sitesRows = $('Read Site Application Tracker').all().map(i => i.json);
const vaultRows = $('Postgres: Load Authenticated Portals').all().map(i => i.json);

const skillsList = skillsRows
  .map(r => String(r['Skill Name'] || r['Skills'] || r['Skill'] || '').trim())
  .filter(Boolean);

const certsList = certsRows
  .map(r => {
    const name = String(r['Name of the Certification'] || r['Certification'] || '').trim();
    const provider = String(r['Provider'] || 'Coursera').trim();
    const date = String(r['Date/Month of Completion'] || '').trim();
    const area = String(r['Area'] || '').trim();
    return name ? { provider, name, date, area } : null;
  })
  .filter(Boolean);

const vaultMap = {};
for (const v of vaultRows) {
  if (v.site_name) vaultMap[String(v.site_name).toLowerCase()] = v;
}

const syncedPortals = [];
const pendingPortals = [];

for (const s of sitesRows) {
  const siteName = String(s['Site'] || s['Site Name'] || s['Portal'] || '').trim();
  if (!siteName) continue;
  const status = String(s['Authentication Status'] || s['Status'] || '').trim();
  const v = vaultMap[siteName.toLowerCase()] || {};
  const isAuth = status.toLowerCase().includes('authenticated') || status.toLowerCase().includes('logged') || v.auth_status === 'Authenticated';
  const authEmail = v.auth_email || 'user@example.com';
  const loginMethod = v.login_method || (status.includes('SSO') ? 'Google SSO' : 'Password');
  if (isAuth) {
    syncedPortals.push({
      siteName,
      loginMethod,
      authEmail,
      commEmail: 'user@example.com',
      skillsSynced: skillsList.length,
      certsSynced: certsList.length
    });
  } else {
    pendingPortals.push(siteName);
  }
}

const tgText =
  `🔄 *Workflow B — All-Portal Profile & Coursera Certificate Sync Complete*\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📧 *Communication Email (Locked):* \`user@example.com\`\n` +
  `🛠️ *Master Skills Synced:* *${skillsList.length}* skills _(${skillsList.slice(0, 6).join(', ')}...)_\n` +
  `🎓 *Certifications Synced:* *${certsList.length}* certificates _(Coursera / Google / Wharton / Udemy)_\n\n` +
  `✅ *Synced Portals (${syncedPortals.length}):*\n` +
  (syncedPortals.map(p => `• *${p.siteName}* — \`${p.loginMethod}\` (\`${p.authEmail}\`)`).join('\n') || '• None') +
  (pendingPortals.length > 0 ? `\n\n🔐 *Pending Auth (${pendingPortals.length}):* ${pendingPortals.join(', ')} _(Use /edit_creds to configure)_` : '');

const tgUrl = `https://api.telegram.org/bot${'YOUR_TELEGRAM_BOT_TOKEN'}/sendMessage`;
try {
  await fetch(tgUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chat_id: '8873019272',
      text: tgText,
      parse_mode: 'Markdown',
      reply_markup: {
        inline_keyboard: [
          [
            { text: '🔐 Manage Portal Credentials', callback_data: 'cmd:edit_creds' },
            { text: '📊 View Pipeline', callback_data: 'cmd:pipeline' }
          ]
        ]
      }
    })
  });
} catch (e) {}

return [{
  json: {
    ok: true,
    skillsCount: skillsList.length,
    certsCount: certsList.length,
    syncedPortalsCount: syncedPortals.length,
    syncedPortals,
    pendingPortals
  }
}];
